import net.minecraftforge.fml.relauncher.ReflectionHelper;
import net.minecraftforge.fml.relauncher.Side;
import net.minecraftforge.fml.relauncher.SideOnly;

import java.util.ArrayList;
import java.util.List;

public class RequirementHolder {

    private static AdvancementList advList;
    private final List<Requirement> requirements;
    private final boolean forcedEmpty;

    public RequirementHolder() {
        this.requirements = Lists.newArrayList();
        this.forcedEmpty = true;
    }

    public RequirementHolder(List<Requirement> requirements) {
        this.requirements = requirements;
        this.forcedEmpty = false;
    }

    public RequirementHolder(RequirementHolder... others) {
        this.forcedEmpty = false;
        this.requirements = Lists.newArrayList();
        //TODO Eventually look into optimizing this. Potentially by presorting others by requirement count
        for (RequirementHolder other : others) {
            for (Requirement otherRequirement : other.requirements) {
                boolean noMatch = true;
                int toRemove = -1;
                for (int i = 0; i < requirements.size(); i++) {
                    RequirementComparision match = requirements.get(i).matches(otherRequirement);
                    if (match.equals(RequirementComparision.EQUAL_TO) || match.equals(RequirementComparision.GREATER_THAN)) {
                        noMatch = false;
                        break;
                    } else if (match.equals(RequirementComparision.LESS_THAN)) {
                        toRemove = i;
                        break;
                    }
                }
                if (toRemove >= 0) {
                    requirements.remove(toRemove);
                }
                if (noMatch) {
                    requirements.add(otherRequirement);
                }
            }
        }
    }

    public static RequirementHolder realEmpty() {
        return new RequirementHolder();
    }

    public static RequirementHolder fromStringList(String[] requirementStringList) {
        List<Requirement> requirements = new ArrayList<>();
        for (String s : requirementStringList) {
            Requirement requirement = ReskillableAPI.getInstance().getRequirementRegistry().getRequirement(s);
            if (requirement != null) {
                requirements.add(requirement);
            }
        }
        return requirements.isEmpty() ? RequirementHolder.realEmpty() : new RequirementHolder(requirements);
    }

    public static RequirementHolder fromString(String s) {
        RequirementHolder requirementHolder;
        if (s.matches("(?i)^(none|null|nil)$")) {
            requirementHolder = RequirementHolder.realEmpty();
        } else {
            requirementHolder = fromStringList(s.split(","));
        }

        return requirementHolder;
    }

    public static AdvancementList getAdvancementList() {
        if (advList == null) {
            advList = ReflectionHelper.getPrivateValue(AdvancementManager.class, null, LibObfuscation.ADVANCEMENT_LIST);
        }
        return advList;
    }

    public boolean isRealLock() {
        return getRestrictionLength() > 0 && !forcedEmpty;
    }

    public boolean isForcedEmpty() {
        return forcedEmpty;
    }

    public int getRestrictionLength() {
        return requirements.size();
    }

    @SideOnly(Side.CLIENT)
    public void addRequirementsToTooltip(PlayerData data, List<String> tooltip) {
        if (!isRealLock()) {
            return;
        }
        if (!ConfigHandler.hideRequirements || GuiScreen.isShiftKeyDown()) {
            tooltip.add(TextFormatting.DARK_PURPLE + I18n.translateToLocal("skillable.misc.skillLock"));
            for (Requirement requirement : requirements) {
                tooltip.add(requirement.getToolTip(data));
            }
        } else {
            tooltip.add(TextFormatting.DARK_PURPLE + I18n.translateToLocal("skillable.misc.skillLockShift"));
        }
    }

    public List<Requirement> getRequirements() {
        return requirements;
    }
}

package codersafterdark.reskillable.api.requirement;

import codersafterdark.reskillable.Reskillable;
import codersafterdark.reskillable.api.ReskillableAPI;
import codersafterdark.reskillable.api.ReskillableRegistries;
import codersafterdark.reskillable.api.skill.Skill;
import com.google.common.collect.Maps;
import net.minecraft.util.ResourceLocation;
import org.apache.logging.log4j.Level;

import java.util.Map;
import java.util.function.Function;

public class RequirementRegistry {
    private Map<String, Function<String, Requirement>> requirementHandlers = Maps.newHashMap();

    public Requirement getRequirement(String requirementString) {
        String[] requirements = requirementString.split("\\|");
        Requirement requirement = null;
        if (requirements.length == 2) {
            String requirementType = requirements[0];
            String requirementInputs = requirements[1];

            if (requirementHandlers.containsKey(requirementType)) {
                requirement = requirementHandlers.get(requirementType).apply(requirementInputs);
            } else {
                try {
                    int level = Integer.parseInt(requirementInputs);
                    Skill skill = ReskillableRegistries.SKILLS.getValue(new ResourceLocation(requirementType));
                    if (skill != null && level > 1) {
                        requirement = new SkillRequirement(skill, level);
                    } else {
                        ReskillableAPI.getInstance().log(Level.WARN, "Invalid Level Lock: " + requirementString);
                    }
                } catch (NumberFormatException e) {
                    ReskillableAPI.getInstance().log(Level.WARN, "Invalid Level Lock: " + requirementString);
                }
            }

        } else if (requirements.length > 2) {
            String requirementType = requirements[0];
            if (requirementHandlers.containsKey(requirementType)) {
                //Pass them the whole extended requirement Inputs (Note: they will have to split by | themselves)
                requirement = requirementHandlers.get(requirementType).apply(requirementString.substring(requirementType.length() + 1));
            }
        }
        if (requirement == null) {
            Reskillable.logger.log(Level.ERROR, "Invalid Lock for Input: " + requirementString);
        } else if (!requirement.isEnabled()) {
            //TODO: potentially let requirements set their own disabled message
            Reskillable.logger.log(Level.ERROR, "Disabled Requirement for Input: " + requirementString);
            requirement = null;
        }
        return requirement;
    }

    public void addRequirementHandler(String identity, Function<String, Requirement> creator) {
        requirementHandlers.put(identity, creator);
    }
}

package codersafterdark.reskillable.api.requirement;

import codersafterdark.reskillable.api.data.PlayerData;
import codersafterdark.reskillable.api.data.PlayerDataHandler;
import codersafterdark.reskillable.api.skill.Skill;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.util.text.TextComponentTranslation;
import net.minecraft.util.text.TextFormatting;

public class SkillRequirement extends Requirement {
    private final Skill skill;
    private final int level;

    public SkillRequirement(Skill skill, int level) {
        this.skill = skill;
        this.level = level;
    }

    @Override
    public boolean achievedByPlayer(EntityPlayer entityPlayer) {
        PlayerData data = PlayerDataHandler.get(entityPlayer);
        return data.getSkillInfo(skill).getLevel() >= level;
    }

    @Override
    public String getToolTip(PlayerData data) {
        TextFormatting color = TextFormatting.GREEN;
        if (data == null || data.getSkillInfo(skill).getLevel() < level) {
            color = TextFormatting.RED;
        }
        return TextFormatting.GRAY + " - " + new TextComponentTranslation("skillable.misc.skillFormat", TextFormatting.DARK_AQUA, skill.getName(), color, level).getUnformattedComponentText();
    }

    public Skill getSkill() {
        return skill;
    }

    public int getLevel() {
        return level;
    }

    @Override
    public RequirementComparision matches(Requirement other) {
        if (other instanceof SkillRequirement) {
            SkillRequirement skillRequirement = (SkillRequirement) other;
            if (getSkill() == null || skillRequirement.getSkill() == null) {
                //If they are both invalid don't bother checking the level.
                return RequirementComparision.NOT_EQUAL;
            }
            if (getSkill().getKey().equals(skillRequirement.getSkill().getKey())) {
                if (getLevel() == skillRequirement.getLevel()) {
                    return RequirementComparision.EQUAL_TO;
                }
                return getLevel() > skillRequirement.getLevel() ? RequirementComparision.GREATER_THAN : RequirementComparision.LESS_THAN;
            }
        }
        return RequirementComparision.NOT_EQUAL;
    }

    @Override
    public boolean isEnabled() {
        return getSkill() != null && getSkill().isEnabled();
    }
}

